const sports=['Fotboll','Golf','Ishockey','Motorsport','Tennis'];
const channels=[['TV4 Play Sport Total','SHL, Allsvenskan, tennis'],['Viaplay Total','NHL, Premier League, F1'],['Prime Video','Utvalda Premier League-matcher'],['Disney+','NHL, La Liga, Europa League'],['HBO Max','Eurosport och internationell sport'],['TV4 Sportkanalen','Sport och studiosändningar'],['V sport premium','Premier League och NHL']];
const events=[
 {sport:'Fotboll',time:'18:30',title:'Darmstadt – Schalke 04',meta:'2. Bundesliga · Mer info, tabell & arena',channel:'V sport football',service:'Viaplay',url:'https://www.google.com/search?q=Darmstadt+Schalke+04+match'},
 {sport:'Fotboll',time:'20:30',title:'Augsburg – Dortmund',meta:'Bundesliga · Mer info, tabell & arena',channel:'V sport premium',service:'Viaplay',url:'https://www.google.com/search?q=Augsburg+Dortmund+match'},
 {sport:'Golf',time:'13:00',title:'DP World Tour',meta:'Dag 2 · Leaderboard & spelplats',channel:'V sport golf',service:'Viaplay',url:'https://www.europeantour.com/dpworld-tour/'},
 {sport:'Ishockey',time:'18:00',title:'Florida Panthers – Dallas Stars',meta:'NHL · Form, senaste möten, tabell & karta',channel:'V sport vinter',service:'Viaplay',url:'https://www.nhl.com/gamecenter/'},
 {sport:'Ishockey',time:'19:00',title:'SHL: Kvällens matcher',meta:'SHL · Matcher, tabell och arenor',channel:'TV4 Hockey',service:'TV4 Play',url:'https://www.shl.se/game-schedule'},
 {sport:'Motorsport',time:'16:00',title:'Formel 1 – träning',meta:'F1 · Tider, bana och förarställning',channel:'V sport motor',service:'Viaplay',url:'https://www.formula1.com/en/racing/2026.html'},
 {sport:'Tennis',time:'11:00',title:'ATP Masters – åttondelsfinaler',meta:'ATP · Lottning, resultat & ranking',channel:'TV4 Tennis',service:'TV4 Play',url:'https://www.atptour.com/en/scores/current'},
 {sport:'Tennis',time:'18:00',title:'WTA Tour – kvartsfinaler',meta:'WTA · Lottning, resultat & ranking',channel:'HBO Max',service:'HBO Max',url:'https://www.wtatennis.com/tournament'}
];
const getPrefs=()=>JSON.parse(localStorage.getItem('sportPrefs')||'null')||{sports:[...sports],channels:channels.map(x=>x[0])};
function renderEvents(filter='Alla'){const root=document.querySelector('#events');if(!root)return;const prefs=getPrefs();const visible=events.filter(e=>prefs.sports.includes(e.sport)&&(filter==='Alla'||e.sport===filter));const groups=Object.groupBy?Object.groupBy(visible,e=>e.sport):visible.reduce((a,e)=>((a[e.sport]??=[]).push(e),a),{});root.innerHTML=Object.keys(groups).sort((a,b)=>a.localeCompare(b,'sv')).map(s=>`<section class="sport-group"><div class="sport-title"><h3>${s}</h3><span>${groups[s].length} SÄNDNING${groups[s].length>1?'AR':''}</span></div>${groups[s].sort((a,b)=>a.time.localeCompare(b.time)).map(e=>`<a class="event" href="${e.url}" target="_blank" rel="noreferrer"><span class="time">${e.time}</span><div><h4>${e.title}</h4><p>${e.meta}</p></div><div class="channel"><b>${e.channel}</b><span>${e.service}</span></div><span class="arrow">↗</span></a>`).join('')}</section>`).join('')||'<div class="empty">Inga valda sändningar att visa.</div>';document.querySelector('#count').textContent=`${visible.length} sändningar`}
document.querySelectorAll('.chip').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.chip').forEach(x=>x.classList.remove('active'));b.classList.add('active');renderEvents(b.dataset.filter)}));renderEvents();
document.querySelector('#refresh')?.addEventListener('click',e=>{e.currentTarget.textContent='✓ Uppdaterad';setTimeout(()=>e.currentTarget.textContent='↻ Uppdatera nu',1800)});
function renderSettings(){const form=document.querySelector('#settings-form');if(!form)return;let prefs=getPrefs();const save=()=>{localStorage.setItem('sportPrefs',JSON.stringify(prefs));const s=document.querySelector('#save-status');s.textContent='✓ Ändringar sparade';};document.querySelector('#sports-options').innerHTML=sports.map(x=>`<label class="option"><input type="checkbox" value="${x}" ${prefs.sports.includes(x)?'checked':''}><span>${x}</span></label>`).join('');document.querySelector('#channel-options').innerHTML=channels.map(([x,d])=>`<label class="option"><input type="checkbox" value="${x}" ${prefs.channels.includes(x)?'checked':''}><span>${x}<small>${d}</small></span></label>`).join('');form.addEventListener('change',e=>{const all=[...form.querySelectorAll('input')];prefs={sports:all.filter(x=>sports.includes(x.value)&&x.checked).map(x=>x.value),channels:all.filter(x=>channels.some(c=>c[0]===x.value)&&x.checked).map(x=>x.value)};save()});document.querySelectorAll('[data-toggle]').forEach(b=>b.addEventListener('click',()=>{const vals=b.dataset.toggle==='sports'?sports:channels.map(x=>x[0]);form.querySelectorAll('input').forEach(i=>{if(vals.includes(i.value))i.checked=true});form.dispatchEvent(new Event('change'));}));}renderSettings();
